-- ==============================================================================
-- BƯỚC 3: NẠP 108 ĐỘC GIẢ, 100 LƯỢT MƯỢN TRẢ, 50 PHIẾU PHẠT, 10 HÓA ĐƠN & 50 LOG AI
-- ==============================================================================

SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

-- 1. Nạp Users độc giả
SET IDENTITY_INSERT Users ON;
SET IDENTITY_INSERT Users OFF;

-- 2. Nạp Readers
SET IDENTITY_INSERT Readers ON;
SET IDENTITY_INSERT Readers OFF;

-- 3. Nạp Borrowings
SET IDENTITY_INSERT Borrowings ON;
SET IDENTITY_INSERT Borrowings OFF;

-- 4. Nạp BorrowingDetails
SET IDENTITY_INSERT BorrowingDetails ON;
SET IDENTITY_INSERT BorrowingDetails OFF;

-- 5. Nạp FineReceipts
SET IDENTITY_INSERT FineReceipts ON;
SET IDENTITY_INSERT FineReceipts OFF;

-- 6. Nạp PenaltyInvoices
SET IDENTITY_INSERT PenaltyInvoices ON;
SET IDENTITY_INSERT PenaltyInvoices OFF;

-- 7. Nạp AIPredictionLogs
SET IDENTITY_INSERT AIPredictionLogs ON;
SET IDENTITY_INSERT AIPredictionLogs OFF;

-- 8. Cập nhật trạng thái bản sao khớp với các lượt mượn đang active/overdue
;WITH ActiveCopies AS (
    SELECT CopyID FROM BorrowingDetails WHERE ItemStatus = 'Borrowed'
)
UPDATE bc SET Status = 'Borrowed'
FROM BookCopies bc JOIN ActiveCopies ac ON ac.CopyID = bc.CopyID;

COMMIT TRANSACTION;
PRINT N'==> BƯỚC 3 HOÀN TẤT: ĐÃ ĐỒNG BỘ ĐẦY ĐỦ ĐỘC GIẢ, MƯỢN TRẢ, PHẠT VÀ AI LOGS!';
